package scaffold

import (
	"fmt"
	"path"
	"strings"
)

// Component is a single piece of project infrastructure that can be added to an
// existing project with "forge add".
type Component struct {
	Name        string
	Description string
	// Patterns select, by path.Match, the files of a rendered project that make up this component.
	Patterns []string
	// Extra, if set, names an optional template set (templates/extras/<Extra>/<lang>) that is
	// rendered instead of filtering a full project. Used for pieces not generated by default.
	Extra string
	// ExcludeTypes lists project types for which the component makes no sense.
	ExcludeTypes []string
}

var components = []Component{
	{Name: "ci", Description: "GitHub Actions CI workflow", Patterns: []string{".github/workflows/*"}},
	{Name: "dockerfile", Description: "Dockerfile and .dockerignore", Extra: "dockerfile", ExcludeTypes: []string{"go-lib", "gleam", "zig", "generic"}},
	{Name: "license", Description: "LICENSE file (see --license)", Patterns: []string{"LICENSE"}},
	{Name: "gitignore", Description: ".gitignore for the project's language", Patterns: []string{".gitignore"}},
	{Name: "editorconfig", Description: ".editorconfig", Patterns: []string{".editorconfig"}},
	{Name: "changelog", Description: "CHANGELOG.md (Keep a Changelog format)", Patterns: []string{"CHANGELOG.md"}},
	{Name: "contributing", Description: "CONTRIBUTING.md", Patterns: []string{"CONTRIBUTING.md"}},
	{Name: "dependabot", Description: "Dependabot config: weekly dependency and CI action updates", Patterns: []string{".github/dependabot.yml"}},
	{Name: "github", Description: "GitHub issue and pull request templates", Patterns: []string{".github/ISSUE_TEMPLATE/*", ".github/pull_request_template.md"}},
	{Name: "docs", Description: "docs/ index and architecture page", Patterns: []string{"docs/*"}},
	{Name: "makefile", Description: "Makefile with standard developer tasks", Patterns: []string{"Makefile"}},
	{Name: "lint", Description: "Linter / formatter configuration", Patterns: []string{".golangci.yml", "rustfmt.toml", "eslint.config.js"}},
}

// Components returns all components that can be added to a project.
func Components() []Component {
	out := make([]Component, len(components))
	copy(out, components)
	return out
}

// ComponentNames returns the names of all components.
func ComponentNames() []string {
	names := make([]string, len(components))
	for i, c := range components {
		names[i] = c.Name
	}
	return names
}

// LookupComponent finds a component by name.
func LookupComponent(name string) (Component, error) {
	for _, c := range components {
		if c.Name == name {
			return c, nil
		}
	}
	return Component{}, fmt.Errorf("unknown component %q (available: %s)", name, strings.Join(ComponentNames(), ", "))
}

// RenderComponent renders just the files of component c for the project described by opts
// (which must already be normalized).
func RenderComponent(opts Options, c Component) ([]File, error) {
	for _, ex := range c.ExcludeTypes {
		if ex == opts.Type {
			return nil, fmt.Errorf("component %q does not apply to project type %q", c.Name, opts.Type)
		}
	}

	var files []File
	if c.Extra != "" {
		var err error
		if files, err = RenderExtra(opts, c.Extra); err != nil {
			return nil, err
		}
	} else {
		all, err := Render(opts)
		if err != nil {
			return nil, err
		}
		for _, f := range all {
			if matchesAny(c.Patterns, f.Path) {
				files = append(files, f)
			}
		}
	}

	if len(files) == 0 {
		return nil, fmt.Errorf("component %q is not available for project type %q", c.Name, opts.Type)
	}
	return files, nil
}

func matchesAny(patterns []string, p string) bool {
	for _, pat := range patterns {
		if ok, _ := path.Match(pat, p); ok {
			return true
		}
	}
	return false
}
